// xterm 自带样式以文本内联（宿主只加载 JS，独立的 lib/client.css 不会被注入——
// 否则 xterm 的隐藏输入 textarea 会裸露成左上角的小输入框）
// @ts-ignore
import xtermCss from 'xterm/css/xterm.css'
// 任务管理窗的样式**直接取自 DSH-better-sidebar**（src/client/SubagentView.module.css 原样拷过来），
// 这样两边的拓扑卡片 / 任务行 / 底部输出坞长得一模一样。类名（subagent* / jobs*）本来就是它那套，
// 这里统一套一层 `.dsh-mt_sav` 作用域，避免和其它插件撞名。
// @ts-ignore
import subagentViewCss from './subagent-view.css'

/** 把一段扁平 CSS 的每个选择器加前缀（这份 CSS 里没有 @media/@keyframes，够用）。
 *  先去掉注释：注释里也有逗号/括号，直接参与选择器切分会产出非法选择器、整条规则被浏览器丢掉。 */
function scopeCss(text: string, scope: string): string {
  return text
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/(^|\})\s*([^{}@]+)\{/g, (_all, brace: string, selectors: string) => {
      const prefixed = selectors
        .split(',')
        .map((s) => s.trim())
        .filter((s) => s !== '')
        .map((s) => scope + ' ' + s)
        .join(',')
      return brace + '\n' + prefixed + '{'
    })
}

