  '.dsh-mt_consoleCard{position:relative;box-sizing:border-box;container-type:inline-size;min-width:0;width:100%;height:auto;display:flex;flex-direction:column;gap:clamp(5px,5cqw,14px);aspect-ratio:1/1;min-height:0;padding:clamp(7px,8cqw,21px);background:linear-gradient(135deg,rgba(255,255,255,.22) 0%,rgba(255,255,255,.07) 30%,rgba(255,255,255,.01) 60%,rgba(0,0,0,.07) 100%),rgba(18,23,32,.24);border:1px solid transparent;border-radius:clamp(8px,6.6cqw,16px);box-shadow:0 10px 28px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.13);cursor:pointer;transition:transform .14s ease,box-shadow .14s ease;overflow:hidden;backdrop-filter:blur(var(--mt-cardBlur,0px)) saturate(1.15)}',
