  '@container (max-width:180px){.dsh-mt_consoleIcon{font-size:clamp(20px,18cqw,31px)}.dsh-mt_consoleName{font-size:clamp(12px,11cqw,20px);line-height:1.25}.dsh-mt_consoleStatus{font-size:clamp(12px,11cqw,22px);line-height:1.25}.dsh-mt_consoleRuntime{font-size:clamp(10px,8cqw,17px);line-height:1.2}.dsh-mt_consolePreview{-webkit-line-clamp:2}}',
  '@container (max-width:118px){.dsh-mt_consoleCardHead{position:absolute;inset:0;width:auto!important;display:flex;align-items:center;justify-content:center!important}.dsh-mt_consoleName,.dsh-mt_consoleDivider,.dsh-mt_consoleStatusRow,.dsh-mt_consolePreview,.dsh-mt_consoleAddLabel{display:none!important}.dsh-mt_consoleIcon{font-size:clamp(22px,30cqw,34px)!important}.dsh-mt_consoleAddPlus{position:absolute;inset:0;display:grid;place-items:center;font-size:clamp(22px,30cqw,34px)!important}}',
  // 三色光效：整卡霓虹描边光晕（像侧栏双圆点的发光质感）——完成=绿、待决=黄；工作=蓝色描边顺时针旋转
  '.dsh-mt_consoleCard-glowDone{border-color:rgba(63,185,80,.9);box-shadow:0 0 8px rgba(63,185,80,.5),0 0 26px rgba(63,185,80,.3),inset 0 0 16px rgba(63,185,80,.07)}',
