  '@property --consoleAngle{syntax:"<angle>";initial-value:0deg;inherits:false}',
  '.dsh-mt_consoleCard-busy{box-shadow:0 0 10px rgba(94,160,255,.55),0 0 34px rgba(79,142,247,.4)}',
  '.dsh-mt_consoleCard-busy::before{content:"";position:absolute;inset:-4px;border-radius:19px;padding:4px;background:conic-gradient(from var(--consoleAngle),transparent 0deg,rgba(94,160,255,0) 25deg,#dcebff 55deg,#9cc6ff 85deg,rgba(94,160,255,0) 125deg,transparent 200deg);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude;animation:consoleAngleSpin 1.4s linear infinite;filter:drop-shadow(0 0 8px rgba(140,190,255,.85));pointer-events:none}',
  '@keyframes consoleAngleSpin{to{--consoleAngle:360deg}}',
  '.dsh-mt_console[data-mt-theme=light] .dsh-mt_consoleCard-busy{box-shadow:0 0 10px rgba(37,99,235,.5),0 0 34px rgba(37,99,235,.32)}',
  '.dsh-mt_console[data-mt-theme=light] .dsh-mt_consoleCard-busy::before{background:conic-gradient(from var(--consoleAngle),transparent 0deg,rgba(37,99,235,0) 25deg,#2563eb 55deg,#38bdf8 85deg,rgba(37,99,235,0) 125deg,transparent 200deg);filter:drop-shadow(0 0 8px rgba(37,99,235,.8))}',
  '.dsh-mt_consoleEmpty{padding:40px 0;text-align:center;font-size:12px;color:var(--mt-text3)}',
  // 创建卡片：虚线 + 居中加号，永远最后一位
